const source = $json;
const rawPriority = String(source.priority ?? '').trim();
const priority = rawPriority.toLowerCase();
const urgent = priority === 'critical' || priority === 'high';
const caseName = String(source.name ?? 'Untitled support case').replace(/["\\]/g, '').trim();
const assigneeId = String(source.assigneeId ?? source.assignee?.id ?? '').trim();
const dueAt = new Date(Date.now() + (urgent ? 2 : 24) * 60 * 60 * 1000).toISOString();
return { json: { ...source, normalizedPriority: priority || 'unspecified', urgent, caseName, assigneeId, dueAt, taskTitle: `[Support Case ${source.id}] ${caseName}`, caseStatus: urgent ? 'Escalated' : 'In progress', slaLabel: urgent ? '2-hour urgent' : '24-hour standard' } };
